-- Load Strategy: append (Blendata sinkOption.mode = Append)
INSERT INTO <%=odiRef.getSchemaName("DSS_ODI_LOG","D")%>.TB_TRANSACTION_SS_ESIM_REJECT (PARTITION_DATE, CDR_ID, CDR_TYPE, PARTNER, OWNER, ICCID, FIRST_INSTALLED, PROFILE_TYPE, EID, SIM_TYPE, CDR_FILENAME, CHK_DUPLICATE, CDR_SOURCE_PATH, FILTER_DTM, CREATE_BY, PROCESS_DATE, STATUS, FILTER_ERROR, ERR_MSG, WORKFLOW_PROCESS_DATE)
SELECT CAST(TO_CHAR(process_date, 'YYYYMMDD') AS NUMBER) AS partition_date ,cdr_id ,cdr_type ,partner ,owner ,iccid ,first_installed ,profile_type ,eid ,sim_type ,cdr_filename ,chk_duplicate ,cdr_source_path ,filter_dtm ,create_by ,process_date ,status ,filter_error ,err_msg ,workflow_process_date FROM ( SELECT cdr_id ,cdr_type ,partner ,owner ,iccid ,first_installed ,profile_type ,eid ,sim_type ,cdr_filename ,chk_duplicate ,source_path AS cdr_source_path ,filter_dtm ,create_by ,SYSDATE as process_date ,status ,case when status='MAN' then filter_error when status='TYP' then type_error else filter_error end as filter_error ,case when status='MAN' then filter_error_msg when status='TYP' then type_error_msg else filter_error_msg end AS err_msg ,workflow_process_date FROM <%=odiRef.getSchemaName("DSS_ODI_LOG","D")%>.tb_staging_ss_esim_raw_temp CROSS JOIN ( SELECT COUNT(*) AS chk_dup_append FROM <%=odiRef.getSchemaName("DSS_ODI_LOG","D")%>.tb_transaction_ss_esim_reject WHERE workflow_process_date = (SELECT workflow_process_date FROM <%=odiRef.getSchemaName("DSS_ODI_LOG","D")%>.tb_staging_ss_esim_landing_to_discovery_workflow_status) ) WHERE status NOT IN ('MAP', 'UNMAP') AND chk_dup_append = 0 )
